tests:
test('adds up several numbers', () => { assert.equal(sumOfArray([1, 2, 3]), 6); });
test('handles negative numbers', () => { assert.equal(sumOfArray([-1, 5, -4]), 0); });
test('empty array gives 0', () => { assert.equal(sumOfArray([]), 0); });

referenceSolution:
function sumOfArray(numbers) {
  let total = 0;
  for (const n of numbers) {
    total += n;
  }
  return total;
}
